    defaultExport: { name: "AutocompleteInvalid", value: "invalid", label: "Invalid", component: AutocompleteInvalidModule.default, snippet: "export default function AutocompleteInvalid() {\n  return (\n    <Field name=\"tag\" invalid className=\"w-64\">\n      <FieldLabel>Tag</FieldLabel>\n      <Autocomplete items={tags}>\n        <AutocompleteInputGroup>\n          <AutocompleteInput placeholder=\"Search tags\" />\n        </AutocompleteInputGroup>\n        <AutocompleteContent>\n          <AutocompleteEmpty>No tags found.</AutocompleteEmpty>\n          <AutocompleteList>\n            {(tag: string) => (\n              <AutocompleteItem key={tag} value={tag}>\n                {tag}\n              </AutocompleteItem>\n            )}\n          </AutocompleteList>\n        </AutocompleteContent>\n      </Autocomplete>\n      <FieldError match>Add a tag to continue.</FieldError>\n    </Field>\n  );\n}" },
    exports: [
    { name: "AutocompleteInvalid", value: "invalid", label: "Invalid", component: AutocompleteInvalidModule.default, snippet: "export default function AutocompleteInvalid() {\n  return (\n    <Field name=\"tag\" invalid className=\"w-64\">\n      <FieldLabel>Tag</FieldLabel>\n      <Autocomplete items={tags}>\n        <AutocompleteInputGroup>\n          <AutocompleteInput placeholder=\"Search tags\" />\n        </AutocompleteInputGroup>\n        <AutocompleteContent>\n          <AutocompleteEmpty>No tags found.</AutocompleteEmpty>\n          <AutocompleteList>\n            {(tag: string) => (\n              <AutocompleteItem key={tag} value={tag}>\n                {tag}\n              </AutocompleteItem>\n            )}\n          </AutocompleteList>\n        </AutocompleteContent>\n      </Autocomplete>\n      <FieldError match>Add a tag to continue.</FieldError>\n    </Field>\n  );\n}" },
    ],
    source: "'use client';\n\nimport { Field, FieldError, FieldLabel } from '@/registry/ui/form';\nimport {\n  Autocomplete,\n  AutocompleteContent,\n  AutocompleteEmpty,\n  AutocompleteInput,\n  AutocompleteInputGroup,\n  AutocompleteItem,\n  AutocompleteList,\n} from '@/registry/ui/autocomplete';\n\nconst tags = [\n  'Accessibility',\n  'Animation',\n  'Bug fix',\n  'Design system',\n  'Documentation',\n  'Performance',\n  'Refactor',\n  'Security',\n  'Testing',\n  'Typography',\n];\n\nexport default function AutocompleteInvalid() {\n  return (\n    <Field name=\"tag\" invalid className=\"w-64\">\n      <FieldLabel>Tag</FieldLabel>\n      <Autocomplete items={tags}>\n        <AutocompleteInputGroup>\n          <AutocompleteInput placeholder=\"Search tags\" />\n        </AutocompleteInputGroup>\n        <AutocompleteContent>\n          <AutocompleteEmpty>No tags found.</AutocompleteEmpty>\n          <AutocompleteList>\n            {(tag: string) => (\n              <AutocompleteItem key={tag} value={tag}>\n                {tag}\n              </AutocompleteItem>\n            )}\n          </AutocompleteList>\n        </AutocompleteContent>\n      </Autocomplete>\n      <FieldError match>Add a tag to continue.</FieldError>\n    </Field>\n  );\n}\n",
