  "checkbox-indeterminate": {
    slug: "checkbox-indeterminate",
    defaultExport: { name: "CheckboxIndeterminate", value: "indeterminate", label: "Indeterminate", component: CheckboxIndeterminateModule.default, snippet: "export default function CheckboxIndeterminate() {\n  const [values, setValues] = React.useState(['email']);\n\n  const allChecked = values.length === OPTIONS.length;\n  const someChecked = values.length > 0 && !allChecked;\n\n  return (\n    <CheckboxGroup value={values} onValueChange={setValues} allValues={OPTIONS.map((o) => o.value)}>\n      <label className=\"flex items-center gap-2\">\n        <Checkbox\n          parent\n          checked={allChecked}\n          indeterminate={someChecked}\n          onCheckedChange={() => setValues(allChecked ? [] : OPTIONS.map((o) => o.value))}\n        />\n        <span className=\"text-sm text-foreground\">All notifications</span>\n      </label>\n      <div className=\"ml-6 flex flex-col gap-2 border-l border-line-subtle pl-4\">\n        {OPTIONS.map((option) => (\n          <label key={option.value} className=\"flex items-center gap-2\">\n            <Checkbox value={option.value} />\n            <span className=\"text-sm text-foreground\">{option.label}</span>\n          </label>\n        ))}\n      </div>\n    </CheckboxGroup>\n  );\n}" },
    exports: [
    { name: "CheckboxIndeterminate", value: "indeterminate", label: "Indeterminate", component: CheckboxIndeterminateModule.default, snippet: "export default function CheckboxIndeterminate() {\n  const [values, setValues] = React.useState(['email']);\n\n  const allChecked = values.length === OPTIONS.length;\n  const someChecked = values.length > 0 && !allChecked;\n\n  return (\n    <CheckboxGroup value={values} onValueChange={setValues} allValues={OPTIONS.map((o) => o.value)}>\n      <label className=\"flex items-center gap-2\">\n        <Checkbox\n          parent\n          checked={allChecked}\n          indeterminate={someChecked}\n          onCheckedChange={() => setValues(allChecked ? [] : OPTIONS.map((o) => o.value))}\n        />\n        <span className=\"text-sm text-foreground\">All notifications</span>\n      </label>\n      <div className=\"ml-6 flex flex-col gap-2 border-l border-line-subtle pl-4\">\n        {OPTIONS.map((option) => (\n          <label key={option.value} className=\"flex items-center gap-2\">\n            <Checkbox value={option.value} />\n            <span className=\"text-sm text-foreground\">{option.label}</span>\n          </label>\n        ))}\n      </div>\n    </CheckboxGroup>\n  );\n}" },
    ],
    source: "'use client';\n\nimport * as React from 'react';\nimport { Checkbox } from '@/registry/ui/checkbox';\nimport { CheckboxGroup } from '@/registry/ui/checkbox-group';\n\nconst OPTIONS = [\n  { value: 'email', label: 'Email updates' },\n  { value: 'push', label: 'Push notifications' },\n  { value: 'sms', label: 'SMS alerts' },\n];\n\nexport default function CheckboxIndeterminate() {\n  const [values, setValues] = React.useState(['email']);\n\n  const allChecked = values.length === OPTIONS.length;\n  const someChecked = values.length > 0 && !allChecked;\n\n  return (\n    <CheckboxGroup value={values} onValueChange={setValues} allValues={OPTIONS.map((o) => o.value)}>\n      <label className=\"flex items-center gap-2\">\n        <Checkbox\n          parent\n          checked={allChecked}\n          indeterminate={someChecked}\n          onCheckedChange={() => setValues(allChecked ? [] : OPTIONS.map((o) => o.value))}\n        />\n        <span className=\"text-sm text-foreground\">All notifications</span>\n      </label>\n      <div className=\"ml-6 flex flex-col gap-2 border-l border-line-subtle pl-4\">\n        {OPTIONS.map((option) => (\n          <label key={option.value} className=\"flex items-center gap-2\">\n            <Checkbox value={option.value} />\n            <span className=\"text-sm text-foreground\">{option.label}</span>\n          </label>\n        ))}\n      </div>\n    </CheckboxGroup>\n  );\n}\n",
  },
