    defaultExport: { name: "ComboboxClearable", value: "clearable", label: "Clearable", component: ComboboxClearableModule.default, snippet: "export default function ComboboxClearable() {\n  return (\n    <Combobox items={fruits} defaultValue=\"Cherry\">\n      <ComboboxInputGroup className=\"w-64\">\n        <ComboboxInput aria-label=\"Fruit\" placeholder=\"Select a fruit\" />\n        <ComboboxClear />\n        <ComboboxTrigger />\n      </ComboboxInputGroup>\n      <ComboboxContent>\n        <ComboboxEmpty>No fruits found.</ComboboxEmpty>\n        <ComboboxList>\n          {(item: string) => (\n            <ComboboxItem key={item} value={item}>\n              {item}\n            </ComboboxItem>\n          )}\n        </ComboboxList>\n      </ComboboxContent>\n    </Combobox>\n  );\n}" },
