  "combobox-groups": {
    slug: "combobox-groups",
    defaultExport: { name: "ComboboxGroups", value: "groups", label: "Groups", component: ComboboxGroupsModule.default, snippet: "export default function ComboboxGroups() {\n  return (\n    <Combobox items={produce}>\n      <ComboboxInputGroup className=\"w-64\">\n        <ComboboxInput aria-label=\"Produce\" placeholder=\"Select produce\" />\n        <ComboboxTrigger />\n      </ComboboxInputGroup>\n      <ComboboxContent>\n        <ComboboxEmpty>No produce found.</ComboboxEmpty>\n        <ComboboxList>\n          {(group: ProduceGroup, index: number) => (\n            <React.Fragment key={group.label}>\n              {index > 0 && <ComboboxSeparator />}\n              <ComboboxGroup items={group.items}>\n                <ComboboxLabel>{group.label}</ComboboxLabel>\n                <ComboboxCollection>\n                  {(item: string) => (\n                    <ComboboxItem key={item} value={item}>\n                      {item}\n                    </ComboboxItem>\n                  )}\n                </ComboboxCollection>\n              </ComboboxGroup>\n            </React.Fragment>\n          )}\n        </ComboboxList>\n      </ComboboxContent>\n    </Combobox>\n  );\n}" },
    exports: [
    { name: "ComboboxGroups", value: "groups", label: "Groups", component: ComboboxGroupsModule.default, snippet: "export default function ComboboxGroups() {\n  return (\n    <Combobox items={produce}>\n      <ComboboxInputGroup className=\"w-64\">\n        <ComboboxInput aria-label=\"Produce\" placeholder=\"Select produce\" />\n        <ComboboxTrigger />\n      </ComboboxInputGroup>\n      <ComboboxContent>\n        <ComboboxEmpty>No produce found.</ComboboxEmpty>\n        <ComboboxList>\n          {(group: ProduceGroup, index: number) => (\n            <React.Fragment key={group.label}>\n              {index > 0 && <ComboboxSeparator />}\n              <ComboboxGroup items={group.items}>\n                <ComboboxLabel>{group.label}</ComboboxLabel>\n                <ComboboxCollection>\n                  {(item: string) => (\n                    <ComboboxItem key={item} value={item}>\n                      {item}\n                    </ComboboxItem>\n                  )}\n                </ComboboxCollection>\n              </ComboboxGroup>\n            </React.Fragment>\n          )}\n        </ComboboxList>\n      </ComboboxContent>\n    </Combobox>\n  );\n}" },
    ],
    source: "'use client';\n\nimport * as React from 'react';\n\nimport {\n  Combobox,\n  ComboboxCollection,\n  ComboboxContent,\n  ComboboxEmpty,\n  ComboboxGroup,\n  ComboboxInput,\n  ComboboxInputGroup,\n  ComboboxItem,\n  ComboboxLabel,\n  ComboboxList,\n  ComboboxSeparator,\n  ComboboxTrigger,\n} from '@/registry/ui/combobox';\n\ninterface ProduceGroup {\n  label: string;\n  items: string[];\n}\n\nconst produce: ProduceGroup[] = [\n  { label: 'Fruits', items: ['Apple', 'Banana', 'Cherry', 'Mango', 'Peach'] },\n  { label: 'Vegetables', items: ['Carrot', 'Celery', 'Kale', 'Spinach', 'Zucchini'] },\n];\n\nexport default function ComboboxGroups() {\n  return (\n    <Combobox items={produce}>\n      <ComboboxInputGroup className=\"w-64\">\n        <ComboboxInput aria-label=\"Produce\" placeholder=\"Select produce\" />\n        <ComboboxTrigger />\n      </ComboboxInputGroup>\n      <ComboboxContent>\n        <ComboboxEmpty>No produce found.</ComboboxEmpty>\n        <ComboboxList>\n          {(group: ProduceGroup, index: number) => (\n            <React.Fragment key={group.label}>\n              {index > 0 && <ComboboxSeparator />}\n              <ComboboxGroup items={group.items}>\n                <ComboboxLabel>{group.label}</ComboboxLabel>\n                <ComboboxCollection>\n                  {(item: string) => (\n                    <ComboboxItem key={item} value={item}>\n                      {item}\n                    </ComboboxItem>\n                  )}\n                </ComboboxCollection>\n              </ComboboxGroup>\n            </React.Fragment>\n          )}\n        </ComboboxList>\n      </ComboboxContent>\n    </Combobox>\n  );\n}\n",
  },
