    source: "'use client';\n\nimport { Button } from '@/registry/ui/button';\nimport { Label } from '@/registry/ui/label';\nimport {\n  Combobox,\n  ComboboxContent,\n  ComboboxEmpty,\n  ComboboxIcon,\n  ComboboxInput,\n  ComboboxInputGroup,\n  ComboboxItem,\n  ComboboxList,\n  ComboboxTrigger,\n  ComboboxValue,\n} from '@/registry/ui/combobox';\n\nconst countries = [\n  'Australia',\n  'Brazil',\n  'Canada',\n  'France',\n  'Germany',\n  'India',\n  'Japan',\n  'Mexico',\n  'Spain',\n  'United Kingdom',\n];\n\nexport default function ComboboxInputInPopup() {\n  return (\n    <div className=\"flex flex-col gap-1.5\">\n      <Label id=\"country-label\">Country</Label>\n      <Combobox items={countries}>\n        <ComboboxTrigger\n          render={<Button variant=\"outline\" className=\"w-56 justify-between font-normal\" />}\n          aria-labelledby=\"country-label\"\n        >\n          <ComboboxValue placeholder=\"Select a country\" />\n          <ComboboxIcon />\n        </ComboboxTrigger>\n        <ComboboxContent aria-label=\"Select a country\" className=\"min-w-56\">\n          <ComboboxInputGroup>\n            <ComboboxInput aria-label=\"Search countries\" placeholder=\"Search countries\" />\n          </ComboboxInputGroup>\n          <ComboboxEmpty>No countries found.</ComboboxEmpty>\n          <ComboboxList>\n            {(item: string) => (\n              <ComboboxItem key={item} value={item}>\n                {item}\n              </ComboboxItem>\n            )}\n          </ComboboxList>\n        </ComboboxContent>\n      </Combobox>\n    </div>\n  );\n}\n",
