    source: "'use client';\n\nimport { Field, FieldError, FieldLabel } from '@/registry/ui/form';\nimport {\n  Combobox,\n  ComboboxContent,\n  ComboboxEmpty,\n  ComboboxInput,\n  ComboboxInputGroup,\n  ComboboxItem,\n  ComboboxList,\n  ComboboxTrigger,\n} from '@/registry/ui/combobox';\n\nconst fruits = [\n  'Apple',\n  'Banana',\n  'Cherry',\n  'Grape',\n  'Kiwi',\n  'Mango',\n  'Orange',\n  'Peach',\n  'Pear',\n  'Strawberry',\n];\n\nexport default function ComboboxInvalid() {\n  return (\n    <Field name=\"fruit\" invalid className=\"w-64\">\n      <FieldLabel>Favourite fruit</FieldLabel>\n      <Combobox items={fruits}>\n        <ComboboxInputGroup>\n          <ComboboxInput placeholder=\"Select a fruit\" />\n          <ComboboxTrigger />\n        </ComboboxInputGroup>\n        <ComboboxContent>\n          <ComboboxEmpty>No fruits found.</ComboboxEmpty>\n          <ComboboxList>\n            {(item: string) => (\n              <ComboboxItem key={item} value={item}>\n                {item}\n              </ComboboxItem>\n            )}\n          </ComboboxList>\n        </ComboboxContent>\n      </Combobox>\n      <FieldError match>Pick a fruit to continue.</FieldError>\n    </Field>\n  );\n}\n",
