    defaultExport: { name: "ComboboxMultiple", value: "multiple", label: "Multiple", component: ComboboxMultipleModule.default, snippet: "export default function ComboboxMultiple() {\n  return (\n    <Combobox items={fruits} multiple defaultValue={['Apple', 'Mango']}>\n      <ComboboxInputGroup className=\"w-72\">\n        <ComboboxValue>\n          {(value: string[]) => (\n            <ComboboxChips>\n              {value.map((fruit) => (\n                <ComboboxChip key={fruit}>\n                  {fruit}\n                  <ComboboxChipRemove aria-label={`Remove ${fruit}`} />\n                </ComboboxChip>\n              ))}\n              <ComboboxInput\n                aria-label=\"Fruits\"\n                placeholder={value.length > 0 ? '' : 'Select fruits'}\n                className=\"h-6 min-w-16 px-0\"\n              />\n            </ComboboxChips>\n          )}\n        </ComboboxValue>\n        <ComboboxTrigger />\n      </ComboboxInputGroup>\n      <ComboboxContent>\n        <ComboboxEmpty>No fruits found.</ComboboxEmpty>\n        <ComboboxList>\n          {(item: string) => (\n            <ComboboxItem key={item} value={item}>\n              {item}\n            </ComboboxItem>\n          )}\n        </ComboboxList>\n      </ComboboxContent>\n    </Combobox>\n  );\n}" },
