    source: "'use client';\n\nimport {\n  Menubar,\n  MenubarContent,\n  MenubarItem,\n  MenubarMenu,\n  MenubarSeparator,\n  MenubarTrigger,\n} from '@/registry/ui/menubar';\n\nfunction EditMenubar({ theme }: { theme: 'gray' | 'accent' }) {\n  return (\n    <Menubar theme={theme}>\n      <MenubarMenu>\n        <MenubarTrigger>File</MenubarTrigger>\n        <MenubarContent>\n          <MenubarItem>New file</MenubarItem>\n          <MenubarItem>Open...</MenubarItem>\n          <MenubarItem>Save</MenubarItem>\n        </MenubarContent>\n      </MenubarMenu>\n      <MenubarMenu>\n        <MenubarTrigger>Edit</MenubarTrigger>\n        <MenubarContent>\n          <MenubarItem>Undo</MenubarItem>\n          <MenubarItem>Redo</MenubarItem>\n          <MenubarSeparator />\n          <MenubarItem>Find</MenubarItem>\n        </MenubarContent>\n      </MenubarMenu>\n      <MenubarMenu>\n        <MenubarTrigger>View</MenubarTrigger>\n        <MenubarContent>\n          <MenubarItem>Zoom in</MenubarItem>\n          <MenubarItem>Zoom out</MenubarItem>\n        </MenubarContent>\n      </MenubarMenu>\n    </Menubar>\n  );\n}\n\nexport function MenubarGray() {\n  return <EditMenubar theme=\"gray\" />;\n}\n\nexport function MenubarAccent() {\n  return <EditMenubar theme=\"accent\" />;\n}\n\nexport default MenubarGray;\n",
