    source: "'use client';\n\nimport {\n  Menubar,\n  MenubarContent,\n  MenubarItem,\n  MenubarMenu,\n  MenubarSeparator,\n  MenubarTrigger,\n} from '@/registry/ui/menubar';\n\nfunction EditMenubar({ variant }: { variant: 'soft' | 'solid' }) {\n  return (\n    <Menubar variant={variant}>\n      <MenubarMenu>\n        <MenubarTrigger>File</MenubarTrigger>\n        <MenubarContent>\n          <MenubarItem>New file</MenubarItem>\n          <MenubarItem>Open...</MenubarItem>\n          <MenubarItem>Save</MenubarItem>\n        </MenubarContent>\n      </MenubarMenu>\n      <MenubarMenu>\n        <MenubarTrigger>Edit</MenubarTrigger>\n        <MenubarContent>\n          <MenubarItem>Undo</MenubarItem>\n          <MenubarItem>Redo</MenubarItem>\n          <MenubarSeparator />\n          <MenubarItem>Find</MenubarItem>\n        </MenubarContent>\n      </MenubarMenu>\n      <MenubarMenu>\n        <MenubarTrigger>View</MenubarTrigger>\n        <MenubarContent>\n          <MenubarItem>Zoom in</MenubarItem>\n          <MenubarItem>Zoom out</MenubarItem>\n        </MenubarContent>\n      </MenubarMenu>\n    </Menubar>\n  );\n}\n\nexport function MenubarSoft() {\n  return <EditMenubar variant=\"soft\" />;\n}\n\nexport function MenubarSolid() {\n  return <EditMenubar variant=\"solid\" />;\n}\n\nexport default MenubarSoft;\n",
