  "navigation-menu-hero": {
    slug: "navigation-menu-hero",
    defaultExport: { name: "NavigationMenuHero", value: "hero", label: "Hero", component: NavigationMenuHeroModule.default, snippet: "export default function NavigationMenuHero() {\n  return (\n    <NavigationMenu>\n      <NavigationMenuList>\n        <NavigationMenuItem>\n          <NavigationMenuTrigger>Products</NavigationMenuTrigger>\n          <NavigationMenuContent>\n            <ul className=\"grid w-80 gap-1\">\n              {PRODUCT_LINKS.map((link) => (\n                <LinkCard key={link.title} {...link} />\n              ))}\n            </ul>\n          </NavigationMenuContent>\n        </NavigationMenuItem>\n        <NavigationMenuItem>\n          <NavigationMenuTrigger>Resources</NavigationMenuTrigger>\n          <NavigationMenuContent>\n            <ul className=\"grid w-80 gap-1\">\n              {RESOURCE_LINKS.map((link) => (\n                <LinkCard key={link.title} {...link} />\n              ))}\n            </ul>\n          </NavigationMenuContent>\n        </NavigationMenuItem>\n        <NavigationMenuItem>\n          <NavigationMenuLink href=\"#\">Pricing</NavigationMenuLink>\n        </NavigationMenuItem>\n      </NavigationMenuList>\n      <NavigationMenuViewport />\n    </NavigationMenu>\n  );\n}" },
    exports: [
    { name: "NavigationMenuHero", value: "hero", label: "Hero", component: NavigationMenuHeroModule.default, snippet: "export default function NavigationMenuHero() {\n  return (\n    <NavigationMenu>\n      <NavigationMenuList>\n        <NavigationMenuItem>\n          <NavigationMenuTrigger>Products</NavigationMenuTrigger>\n          <NavigationMenuContent>\n            <ul className=\"grid w-80 gap-1\">\n              {PRODUCT_LINKS.map((link) => (\n                <LinkCard key={link.title} {...link} />\n              ))}\n            </ul>\n          </NavigationMenuContent>\n        </NavigationMenuItem>\n        <NavigationMenuItem>\n          <NavigationMenuTrigger>Resources</NavigationMenuTrigger>\n          <NavigationMenuContent>\n            <ul className=\"grid w-80 gap-1\">\n              {RESOURCE_LINKS.map((link) => (\n                <LinkCard key={link.title} {...link} />\n              ))}\n            </ul>\n          </NavigationMenuContent>\n        </NavigationMenuItem>\n        <NavigationMenuItem>\n          <NavigationMenuLink href=\"#\">Pricing</NavigationMenuLink>\n        </NavigationMenuItem>\n      </NavigationMenuList>\n      <NavigationMenuViewport />\n    </NavigationMenu>\n  );\n}" },
    ],
    source: "'use client';\n\nimport {\n  NavigationMenu,\n  NavigationMenuContent,\n  NavigationMenuItem,\n  NavigationMenuLink,\n  NavigationMenuList,\n  NavigationMenuTrigger,\n  NavigationMenuViewport,\n} from '@/registry/ui/navigation-menu';\n\nconst PRODUCT_LINKS = [\n  { title: 'Analytics', description: 'Track traffic and conversions across every page.' },\n  { title: 'Automations', description: 'Send follow-ups when a visitor takes an action.' },\n  { title: 'Integrations', description: 'Connect the tools your team already uses.' },\n];\n\nconst RESOURCE_LINKS = [\n  { title: 'Guides', description: 'Step-by-step walkthroughs for common setups.' },\n  { title: 'API reference', description: 'Every endpoint, with request and response examples.' },\n  { title: 'Changelog', description: 'What shipped this month.' },\n];\n\nfunction LinkCard({ title, description }: { title: string; description: string }) {\n  return (\n    <li>\n      <NavigationMenuLink href=\"#\">\n        <span className=\"font-medium\">{title}</span>\n        <span className=\"text-secondary\">{description}</span>\n      </NavigationMenuLink>\n    </li>\n  );\n}\n\nexport default function NavigationMenuHero() {\n  return (\n    <NavigationMenu>\n      <NavigationMenuList>\n        <NavigationMenuItem>\n          <NavigationMenuTrigger>Products</NavigationMenuTrigger>\n          <NavigationMenuContent>\n            <ul className=\"grid w-80 gap-1\">\n              {PRODUCT_LINKS.map((link) => (\n                <LinkCard key={link.title} {...link} />\n              ))}\n            </ul>\n          </NavigationMenuContent>\n        </NavigationMenuItem>\n        <NavigationMenuItem>\n          <NavigationMenuTrigger>Resources</NavigationMenuTrigger>\n          <NavigationMenuContent>\n            <ul className=\"grid w-80 gap-1\">\n              {RESOURCE_LINKS.map((link) => (\n                <LinkCard key={link.title} {...link} />\n              ))}\n            </ul>\n          </NavigationMenuContent>\n        </NavigationMenuItem>\n        <NavigationMenuItem>\n          <NavigationMenuLink href=\"#\">Pricing</NavigationMenuLink>\n        </NavigationMenuItem>\n      </NavigationMenuList>\n      <NavigationMenuViewport />\n    </NavigationMenu>\n  );\n}\n",
  },
  "navigation-menu-large-menu": {
    slug: "navigation-menu-large-menu",
    defaultExport: { name: "NavigationMenuLargeMenu", value: "large-menu", label: "Large Menu", component: NavigationMenuLargeMenuModule.default, snippet: "export default function NavigationMenuLargeMenu() {\n  return (\n    <NavigationMenu>\n      <NavigationMenuList>\n        <NavigationMenuItem>\n          <NavigationMenuTrigger>Locations</NavigationMenuTrigger>\n          <NavigationMenuContent>\n            <ul className=\"grid w-64 gap-0.5\">\n              {REGIONS.map((region) => (\n                <li key={region}>\n                  <NavigationMenuLink href=\"#\">{region}</NavigationMenuLink>\n                </li>\n              ))}\n            </ul>\n          </NavigationMenuContent>\n        </NavigationMenuItem>\n      </NavigationMenuList>\n      <NavigationMenuViewport />\n    </NavigationMenu>\n  );\n}" },
    exports: [
    { name: "NavigationMenuLargeMenu", value: "large-menu", label: "Large Menu", component: NavigationMenuLargeMenuModule.default, snippet: "export default function NavigationMenuLargeMenu() {\n  return (\n    <NavigationMenu>\n      <NavigationMenuList>\n        <NavigationMenuItem>\n          <NavigationMenuTrigger>Locations</NavigationMenuTrigger>\n          <NavigationMenuContent>\n            <ul className=\"grid w-64 gap-0.5\">\n              {REGIONS.map((region) => (\n                <li key={region}>\n                  <NavigationMenuLink href=\"#\">{region}</NavigationMenuLink>\n                </li>\n              ))}\n            </ul>\n          </NavigationMenuContent>\n        </NavigationMenuItem>\n      </NavigationMenuList>\n      <NavigationMenuViewport />\n    </NavigationMenu>\n  );\n}" },
    ],
    source: "'use client';\n\nimport {\n  NavigationMenu,\n  NavigationMenuContent,\n  NavigationMenuItem,\n  NavigationMenuLink,\n  NavigationMenuList,\n  NavigationMenuTrigger,\n  NavigationMenuViewport,\n} from '@/registry/ui/navigation-menu';\n\nconst REGIONS = [\n  'Amsterdam',\n  'Auckland',\n  'Berlin',\n  'Buenos Aires',\n  'Cairo',\n  'Cape Town',\n  'Copenhagen',\n  'Dubai',\n  'Dublin',\n  'Helsinki',\n  'Hong Kong',\n  'Istanbul',\n  'Lagos',\n  'Lisbon',\n  'London',\n  'Madrid',\n  'Mexico City',\n  'Mumbai',\n  'Nairobi',\n  'New York',\n  'Oslo',\n  'Paris',\n  'Reykjavik',\n  'Rio de Janeiro',\n  'Seoul',\n  'Singapore',\n  'Stockholm',\n  'Sydney',\n  'Tokyo',\n  'Toronto',\n];\n\nexport default function NavigationMenuLargeMenu() {\n  return (\n    <NavigationMenu>\n      <NavigationMenuList>\n        <NavigationMenuItem>\n          <NavigationMenuTrigger>Locations</NavigationMenuTrigger>\n          <NavigationMenuContent>\n            <ul className=\"grid w-64 gap-0.5\">\n              {REGIONS.map((region) => (\n                <li key={region}>\n                  <NavigationMenuLink href=\"#\">{region}</NavigationMenuLink>\n                </li>\n              ))}\n            </ul>\n          </NavigationMenuContent>\n        </NavigationMenuItem>\n      </NavigationMenuList>\n      <NavigationMenuViewport />\n    </NavigationMenu>\n  );\n}\n",
  },
